.accordion button { display: block; width: 100%; border: 0; padding: 1rem; text-align: left; font: inherit; font-weight: 650; color: #182236; background: #edf2fa; cursor: pointer; }
.accordion button:focus-visible { position: relative; outline: 3px solid #184ab0; outline-offset: -4px; }
.accordion button[aria-expanded="true"] { background: #dae7fb; }
.accordion [role="region"] { padding: 0 1rem; }
.accordion [hidden] { display: none; }

