import "./styles.css";

document.querySelector("#app").innerHTML = `<main>
  <h1>Workshop questions</h1>
  <p>Open any questions you need. More than one answer may stay open.</p>
  <div class="accordion">
    <h2><button type="button" id="question-supplies" aria-expanded="false" aria-controls="answer-supplies">What should I bring?</button></h2>
    <div id="answer-supplies" role="region" aria-labelledby="question-supplies" hidden><p>Bring a water bottle, a pencil, and a notebook. We supply the tools for the workshop.</p></div>
    <h2><button type="button" id="question-arrival" aria-expanded="false" aria-controls="answer-arrival">When can I arrive?</button></h2>
    <div id="answer-arrival" role="region" aria-labelledby="question-arrival" hidden><p>The studio opens at 09:30. The first workshop begins at 10:00.</p></div>
    <h2><button type="button" id="question-access" aria-expanded="false" aria-controls="answer-access">Is the studio step-free?</button></h2>
    <div id="answer-access" role="region" aria-labelledby="question-access" hidden><p>The main entrance and all workshop rooms are on the ground floor. Contact the host if you need other arrangements.</p></div>
  </div>
</main>`;

for (const button of document.querySelectorAll(".accordion button")) {
  button.addEventListener("click", () => {
    const panel = document.getElementById(button.getAttribute("aria-controls"));
    const expanded = button.getAttribute("aria-expanded") === "true";
    button.setAttribute("aria-expanded", String(!expanded));
    panel.hidden = expanded;
  });
}

