import { useState } from "react";

const questions = [
  {
    "id": "supplies",
    "title": "What should I bring?",
    "answer": "Bring a water bottle, a pencil, and a notebook. We supply the tools for the workshop."
  },
  {
    "id": "arrival",
    "title": "When can I arrive?",
    "answer": "The studio opens at 09:30. The first workshop begins at 10:00."
  },
  {
    "id": "access",
    "title": "Is the studio step-free?",
    "answer": "The main entrance and all workshop rooms are on the ground floor. Contact the host if you need other arrangements."
  }
];

export default function App() {
  const [open, setOpen] = useState([]);
  function toggle(id) {
    setOpen((previous) => previous.includes(id) ? previous.filter((item) => item !== id) : [...previous, id]);
  }

  return (
    <main>
      <h1>Workshop questions</h1>
      <p>Open any questions you need. More than one answer may stay open.</p>
      <div className="accordion">
        {questions.map((question) => (
          <section key={question.id}>
            <h2>
              <button type="button" id={`question-${question.id}`} aria-expanded={open.includes(question.id)} aria-controls={`answer-${question.id}`} onClick={() => toggle(question.id)}>
                {question.title}
              </button>
            </h2>
            <div id={`answer-${question.id}`} role="region" aria-labelledby={`question-${question.id}`} hidden={!open.includes(question.id)}>
              <p>{question.answer}</p>
            </div>
          </section>
        ))}
      </div>
    </main>
  );
}

